/* Combines IELTS assessment with LaTeX document views. PDF remains a labelled mock. */
model.latexIelts ||= {studentView:'text',tutorView:'text',sources:{},origins:{}};
const texEscape=value=>String(value??'').replace(/[\\{}%&#_$~^]/g,c=>({'\\':'\\textbackslash{}','{':'\\{','}':'\\}','%':'\\%','&':'\\&','#':'\\#','_':'\\_','$':'\\$','~':'\\textasciitilde{}','^':'\\textasciicircum{}'}[c]));
function answerTex(text,task){return `\\documentclass[12pt,a4paper]{article}
% Compile with XeLaTeX. The prototype does not compile this source.
\\usepackage{fontspec}
\\setmainfont{TeX Gyre Termes}
\\usepackage[margin=2.5cm]{geometry}
\\usepackage{hyperref}
\\title{IELTS Writing -- Task ${task}}
\\author{Tran An}
\\date{}
\\begin{document}
\\maketitle
\\section*{Task ${task} response}
${texEscape(text)}
\\end{document}
`}
function sourceFor(task,submitted=false){
  if(submitted)return model.submission?.latexSources?.[task]||answerTex(model.submission?.answers[task]||'',task);
  return model.latexIelts.sources[task]||answerTex(model.answers[task],task);
}
function formatTabs(view,scope){return `<div class="ielts-strip hybrid-tabs"><span>IELTS × LaTeX</span>${[['text','Văn bản'],['latex','LaTeX source'],['pdf','PDF preview']].map(([id,name])=>`<button class="${view===id?'primary':''}" data-document-view="${id}" data-document-scope="${scope}">${name}</button>`).join('')}${scope==='student'?button('Tạo/cập nhật LaTeX','latex-generate'):button('Tạo phiếu LaTeX','latex-report')}<small>${scope==='student'?'Văn bản là nội dung chấm IELTS; source là nhánh trình bày.':'Đọc bản đã nộp, band và phản hồi luôn ở cột bên phải.'}</small></div>`}
function pdfMock(text,task){return `<div class="hybrid-pdf-stage"><article class="paper"><div class="paper-caption">BỐ CỤC PDF MINH HỌA · CHƯA BIÊN DỊCH LATEX THẬT</div><h2>IELTS Writing — Task ${task}</h2><p class="subtle">Trần An · ${count(text)} từ nội dung</p>${escape(text).split(/\n\s*\n/).map(p=>`<p>${p}</p>`).join('')}</article></div>`}
function reportTex(){
  const s=model.submission,p=model.published,ts=p?.tasks||s?.tasks||[model.task];
  const scores=p?.scores||model.scores,notes=p?.notes||model.notes;
  return `\\documentclass[11pt,a4paper]{article}
% XeLaTeX report, generated by the IELTS design prototype.
\\usepackage{fontspec}
\\setmainfont{TeX Gyre Termes}
\\usepackage[margin=2cm]{geometry}
\\usepackage{longtable}
\\usepackage{hyperref}
\\title{IELTS Writing -- Phiếu phản hồi}
\\author{Tutor: Nguyễn Minh}
\\date{}
\\begin{document}
\\maketitle
\\noindent Học viên: Trần An\\\\
Trạng thái: ${p?'Đã công bố':'Bản nháp -- chưa công bố'}\\\\
Lần nộp: ${s?.attempt||'Chưa nộp'}
${ts.map(t=>`\\section*{Task ${t}}
\\begin{longtable}{p{.28\\textwidth} p{.08\\textwidth} p{.52\\textwidth}}
Tiêu chí & Band & Nhận xét \\\\ \\hline
${criterion(t,s?.variant||model.variant).map((c,i)=>`${texEscape(c.code+' -- '+c.title)} & ${scores[t][i]??'--'} & ${texEscape(notes[t][i]||'Chưa có nhận xét.')} \\\\`).join('\n')}
\\end{longtable}`).join('\n')}
\\section*{Nhận xét chung và hướng luyện tiếp}
${texEscape(p?.summary||model.summary||'Chưa có nhận xét chung.')}
\\par\\smallskip
\\textit{Band ước tính phục vụ luyện tập, không phải kết quả thi IELTS chính thức.}
\\end{document}
`;
}
const hybridBaseRender=render;
render=function(){
  model.latexIelts ||= {studentView:'text',tutorView:'text',sources:{},origins:{}};
  hybridBaseRender();
  if(model.screen==='practice'){
    const view=model.latexIelts.studentView;
    $('.answer-top').insertAdjacentHTML('afterend',formatTabs(view,'student'));
    if(view==='latex'){
      const stale=model.latexIelts.sources[model.task]&&model.latexIelts.origins[model.task]!==model.answers[model.task];
      $('.answer-sheet').innerHTML=`<p class="hybrid-note">Source trình bày có thể chỉnh. Nội dung chấm và số từ vẫn lấy từ tab Văn bản; sửa LaTeX không tự sửa lại bài tiếng Anh.${stale?' <strong>Văn bản đã đổi; cần tạo lại source để khớp nội dung.</strong>':''}</p><textarea id="latex-answer" aria-label="LaTeX bài viết Task ${model.task}" spellcheck="false">${escape(sourceFor(model.task))}</textarea>`;
    }
    if(view==='pdf')$('.answer-sheet').innerHTML=pdfMock(model.answers[model.task],model.task);
    $('.small-info').textContent='Bài IELTS + source LaTeX cùng workspace · PDF ở prototype chỉ minh họa · không tự đồng bộ hai chiều';
  }
  if(model.screen==='grading'&&model.submission){
    const view=model.latexIelts.tutorView,pane=$('.grade-response');
    pane.insertAdjacentHTML('afterbegin',formatTabs(view,'tutor'));
    if(view==='latex')pane.querySelector('.reading-answer').outerHTML=`<pre class="hybrid-source readonly-source">${escape(sourceFor(model.task,true))}</pre><p class="hybrid-note">Source thuộc bản nộp. Không lấy working copy hiện tại của học viên.</p>`;
    if(view==='pdf')pane.querySelector('.reading-answer').outerHTML=pdfMock(model.submission.answers[model.task],model.task);
  }
  if(model.screen==='tutor')$('.tutor-guide').insertAdjacentHTML('beforebegin',`<div class="ielts-notice"><strong>IELTS kết hợp LaTeX</strong><br>Mở bài chấm để chuyển giữa Văn bản / LaTeX source / PDF preview; cột band IELTS giữ nguyên. Sau chấm, tạo phiếu phản hồi dưới dạng source LaTeX.</div>`);
};
document.addEventListener('input',e=>{if(e.target.id==='latex-answer'){model.latexIelts.sources[model.task]=e.target.value;model.latexIelts.origins[model.task]??=model.answers[model.task];persist()}});
document.addEventListener('click',e=>{
  const el=e.target.closest('button');if(!el||el.disabled)return;
  if(el.dataset.documentView){model.latexIelts[el.dataset.documentScope==='student'?'studentView':'tutorView']=el.dataset.documentView;persist();render();return;}
  const a=el.dataset.action;
  if(a==='latex-generate')openModal('Tạo source LaTeX từ bài IELTS?','<p>Giữ nguyên bài tiếng Anh, tạo hoặc cập nhật source để dàn trang. Nếu đã sửa source, xác nhận này thay source nhánh demo; không tự đồng bộ hai chiều.</p>','latex-generate-confirm','Tạo source');
  if(a==='latex-generate-confirm'){model.latexIelts.sources[model.task]=answerTex(model.answers[model.task],model.task);model.latexIelts.origins[model.task]=model.answers[model.task];model.latexIelts.studentView='latex';persist();$('#modal').close();render();}
  if(a==='submit'&&model.submission){model.submission.latexSources={};for(const t of model.submission.tasks){const fresh=model.latexIelts.origins[t]===model.submission.answers[t];model.submission.latexSources[t]=fresh?sourceFor(t):answerTex(model.submission.answers[t],t);}persist();}
  if(a==='latex-report'||a==='export')openModal('Phiếu chấm IELTS bằng LaTeX',`<p class="hybrid-note">Đây là source .tex có thể tải thật. Compile PDF bằng XeLaTeX trong app chính sau khi tích hợp. Prototype không giả xuất PDF.</p><pre class="hybrid-source report-source">${escape(reportTex())}</pre>`,'latex-download','Tải phiếu .tex');
  if(a==='latex-download'){const blob=new Blob([reportTex()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='ielts-feedback.tex';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
render();
